import re
import os
import logging
import six
from typing import Union, List  # noqa: F401
from functools import partial
from taf.config.testline.cloud_hosting import DeploymentVnfStack  # noqa: F401
from taf.config.testline.gnb.cu import CU  # noqa: F401
from taf.cloud.openstack.yaml_helper import load_yaml, save_dict_as_yaml
from taf.cloud.openstack.connection import verify_connection
from taf.cloud.openstack.exceptions import AmbiguousInstanceName
from taf.cloud.openstack.exceptions import NetworkNotFound
from taf.cloud.openstack.exceptions import InvalidStackOutput
from taf.cloud.openstack.stack import Stack
from taf.cloud.openstack.stack_environment_store import PreparedEnvironments


class Network(object):
    DEFAULT_NETWORKS_TO_UPDATE = ('oam', 'fronthaul', 'backhaul')
    VNF = 'vnf_name'
    DEFAULT_NETWORK_NAME_PATTERN = "{vnf_name}-{name}_net-v{ip_ver}"
    NETWORK_NAME_DEFAULTS = {VNF: 'vBTS'}
    ENV_KEY_TO_NETWORK_NAME_MAP = {
        'oam_network': 'oam',
        'f1m': 'fronthaul', 'f1c': 'fronthaul', 'f1u': 'fronthaul',
        's1u': 'backhaul', 'x2u': 'backhaul', 'x2c': 'backhaul',
        's1c': 'backhaul'}
    CU_NETWORK_ADDRESSES = ('backhaul_site_oam_ip', 'f1m', 'f1c', 'x2c', 'f1u',
                            'x2u', 's1u', 's1c', 'tracing')

    def __init__(self, connection):
        verify_connection(connection)
        self.connection = connection

    def update_ids_using_stack_output(
            self,
            ext_net_stack_name_or_id,
            deployment_vnf_stack,
            env_key_to_name=ENV_KEY_TO_NETWORK_NAME_MAP,
            cu=None):
        # type: (Union[str, List[str]], DeploymentVnfStack, dict, CU) -> None

        if isinstance(ext_net_stack_name_or_id, six.string_types):
            ext_net_stack_name_or_id = [ext_net_stack_name_or_id]
        network_names_with_ids = self._get_stack_output(
            ext_net_stack_name_or_id)

        # Update stack's configuration_data for backward compatibility
        # TODO: remove legacy part in 3.0.0
        if deployment_vnf_stack.configuration_data is not None:
            warn_msg = "Using stack's `configuration_data` attribute is " \
                       "deprecated. Set this attribute to `None` to use the " \
                       "maintained Network.update_ids_using_stack_output " \
                       "method."
            logging.warning(warn_msg)

            parameters = deployment_vnf_stack.configuration_data
            self._fill_network_ids(
                cu=cu,
                env_key_to_name=env_key_to_name,
                network_names_with_ids=network_names_with_ids,
                parameters=parameters)

        else:
            stack_environments = self._get_stack_environments(
                deployment_vnf_stack)
            for stack_environment_info in stack_environments:

                stack_environment = stack_environment_info[0]
                env_path = stack_environment_info[1]

                parameters = stack_environment['parameters']
                changes_count = self._fill_network_ids(
                    cu=cu,
                    env_key_to_name=env_key_to_name,
                    network_names_with_ids=network_names_with_ids,
                    parameters=parameters)

                if changes_count > 0:
                    self._save_stack_environment(stack_environment,
                                                 env_path,
                                                 deployment_vnf_stack)

    def _fill_network_ids(self,
                          cu,
                          env_key_to_name,
                          network_names_with_ids,
                          parameters):
        if cu is not None:
            env_key_to_name = {}

            vlan_id_to_network_id = self._get_segmentation_id_to_network_id(
                network_names_with_ids.values())
            cu_attribute_to_vlan_id = self._get_cu_attribute_to_vlan_id(cu)

            get_network_id = partial(self._get_network_id_from_vlan_mapping,
                                     cu_attribute_to_vlan_id,
                                     vlan_id_to_network_id)
        else:
            get_network_id = partial(self._get_network_id_from_name_mapping,
                                     network_names_with_ids)

        changes_count = self._fill_ids(parameters=parameters,
                                       get_network_id=get_network_id,
                                       env_key_to_name=env_key_to_name)
        return changes_count

    def _fill_ids(self,
                  parameters,
                  get_network_id,
                  env_key_to_name,
                  last_key=None,
                  changes_count=0):
        for key, value in parameters.items():

            if value is None:
                mapped_param_key = self._get_mapped_env_key(
                    env_key=key,
                    env_key_to_network_name_map=env_key_to_name,
                    last_key=last_key)

                identifier = get_network_id(short_network_name=mapped_param_key)
                if identifier:
                    parameters[key] = identifier
                    changes_count += 1

            elif isinstance(value, dict):
                changes_count = self._fill_ids(
                    parameters=value,
                    get_network_id=get_network_id,
                    env_key_to_name=env_key_to_name,
                    last_key=key,
                    changes_count=changes_count)

        return changes_count

    def _get_segmentation_id_to_network_id(self, ids):
        sid_to_id = {}
        for id_ in ids:
            network = self.find_network(id_)
            if network is None:
                exc_msg = "Network '{}' was not found and its " \
                          "identifier cannot be updated in VNF configuration."
                raise NetworkNotFound(exc_msg.format(id_))
            sid_to_id[network.provider_segmentation_id] = network.id
        return sid_to_id

    def find_network(self, name):
        try:
            return self.connection.network.find_network(name)
        # TODO: this should be removed. openstacksdk throws AttributeError when
        # TODO: the network is not found on newer openstack platform
        except AttributeError:
            return None

    def _get_mapped_env_key(
            self, env_key, env_key_to_network_name_map, last_key):
        if env_key == 'uuid':
            mapped_key = last_key
        else:
            mapped_key = env_key

        if mapped_key in env_key_to_network_name_map:
            mapped_key = env_key_to_network_name_map[mapped_key]

        return mapped_key

    def _get_cu_attribute_to_vlan_id(self, cu):
        result = {}

        for attribute in self.CU_NETWORK_ADDRESSES:
            try:
                value = getattr(cu, attribute)
                result[attribute] = value.vlan_id
            except AttributeError:
                pass
        return result

    @staticmethod
    def _get_network_id_from_name_mapping(full_name_to_id, short_network_name):
        found_network_ids = [network_id for network_name, network_id
                             in full_name_to_id.items()
                             if short_network_name in network_name]
        if len(found_network_ids) == 1:
            return found_network_ids[0]

    @staticmethod
    def _get_network_id_from_vlan_mapping(cu_attribute_to_vlan_id,
                                          vlan_id_to_network_id,
                                          short_network_name):
        found_vlan_ids = [vlan_id for cu_attrib, vlan_id
                          in cu_attribute_to_vlan_id.items()
                          if short_network_name in cu_attrib]

        if len(found_vlan_ids) == 1:
            vlan_id = found_vlan_ids[0]
            return vlan_id_to_network_id[vlan_id]

    def _get_stack_output(self, stack_names_or_ids):
        """Creates dictionary `full_network_name: network_id`.
        We are assuming that output is a string in the following form:
        'vBTS-oam_net_T01_net-v4: id0\nvBTS-fronthaul_net_T01_net-v4: id1'
        """
        output = {}
        stack = Stack(self.connection)

        for name_or_id in stack_names_or_ids:
            found_stack = stack.find_stack(name_or_id=name_or_id)

            name_to_id = self._get_network_name_to_id(found_stack)
            output.update(name_to_id)

        return output

    def _get_network_name_to_id(self, found_stack):
        name_to_id = {}
        pattern = re.compile(
            r'^([0-9a-zA-Z_-]+)'  # Network name
            r':\s'  # Separator
            r'([0-9a-zA-Z_-]+)$')  # Network id

        try:
            output_parts = self._extract_output_parts(found_stack)
            for output_part in output_parts:
                network_name, network_id = pattern.findall(output_part)[0]
                name_to_id[network_name] = network_id

        except (AttributeError, TypeError, IndexError):
            self._raise_invalid_stack_output(found_stack.outputs)

        return name_to_id

    def _extract_output_parts(self, found_stack):
        # Assume that found_stack.outputs is a list containing exactly one item
        return found_stack.outputs[0]['output_value'].strip().splitlines()

    def _raise_invalid_stack_output(self, outputs):
        exc_msg = "The first element of the stack outputs should contain " \
                  "'output_value' key. The value should be a string in the " \
                  "form 'network_name: network_id'. Actual outputs: {}"
        exc_msg = exc_msg.format(outputs)
        raise InvalidStackOutput(exc_msg)

    def _get_stack_environments(self, deploy_env):
        result = []
        for env in deploy_env.env_files:
            configuration_data = load_yaml(env)
            result.append((configuration_data, env))
        return result

    def _save_stack_environment(self,
                                stack_environment,
                                file_path,
                                stack):
        """ Save environment with updated network ids. The saved environment
        must be merged AFTER the environment with updated IMAGE parameters."""
        dirname = os.path.dirname(file_path)
        filename, ext = os.path.splitext(file_path)
        new_filename = os.path.basename(filename) + '_updated'
        dest_path = save_dict_as_yaml(stack_environment,
                                      dest_dir=dirname,
                                      prefix=new_filename)
        PreparedEnvironments.add_stack_environment(stack, dest_path, index=0)

    def update_ids(self, deploy_env, net_env,
                   network_list=DEFAULT_NETWORKS_TO_UPDATE,
                   network_name_pattern=DEFAULT_NETWORK_NAME_PATTERN,
                   network_name_defaults=NETWORK_NAME_DEFAULTS):
        network_ids = {}
        networks = list(self.connection.network.networks())
        for network_index, network in enumerate(network_list):
            network_name = self._get_network_name(net_env, network_index)
            found_networks = self._get_networks_with_name(network_name,
                                                          networks)

            if len(found_networks) > 1:
                full_network_name = self._get_full_network_name_using_pattern(
                    net_env,
                    network_index,
                    network_name_pattern,
                    network_name_defaults)
                found_networks = self._get_networks_with_name(
                    full_network_name,
                    networks)

            self._verify_one_network_found(found_networks, network_name)
            network_ids[network] = found_networks[0].id

        self._set_network_ids(deploy_env, network_ids)

    def _set_network_ids(self, deploy_env, network_ids):
        oam_id = network_ids.get('oam')
        if oam_id is not None:
            deploy_env.oam_network = oam_id
        fronthaul_id = network_ids.get('fronthaul')
        if fronthaul_id is not None:
            deploy_env.external_networks['fronthaul'] = fronthaul_id
        backhaul_id = network_ids.get('backhaul')
        if backhaul_id is not None:
            deploy_env.external_networks['backhaul'] = backhaul_id
        tracing_id = network_ids.get('tracing')
        if tracing_id is not None:
            deploy_env.external_networks['tracing'] = tracing_id

    @staticmethod
    def _verify_one_network_found(networks, network_name):
        if not len(networks):
            raise NetworkNotFound("Network with name {} does not exist".format(
                network_name))
        elif len(networks) > 1:
            exc_msg = "Found more than one network with name {}: {}"
            exc_msg = exc_msg.format(network_name, networks)
            raise AmbiguousInstanceName(exc_msg)

    def _get_full_network_name_using_pattern(self, net_env, network_index,
                                             network_name_pattern,
                                             network_name_defaults):
        options = self._get_network_options(network_index, net_env)
        full_network_name = self._get_network_name_by_pattern(
            options=options,
            network_name_pattern=network_name_pattern,
            defaults=network_name_defaults)
        return full_network_name

    @staticmethod
    def _get_network_name_by_pattern(options, network_name_pattern, defaults):
        options_with_defaults = dict(defaults)
        options_with_defaults.update(options)
        return network_name_pattern.format(**options_with_defaults)

    @staticmethod
    def _get_network_name(net_env, network_index):
        return net_env.network_opts['networks'][network_index]['name']

    @classmethod
    def _get_networks_with_name(cls, network_name, networks):
        filtered_networks = list(filter(lambda n: network_name in n.name,
                                        networks))
        return filtered_networks

    @classmethod
    def _get_network_options(cls, i, net_env):
        options = net_env.network_opts['networks'][i]
        if net_env.network_opts.get(cls.VNF) is not None:
            options.update(vnf_name=net_env.network_opts[cls.VNF])
        return options
